
import {
  __, hasRoute,
  html,
  module,
  route,
  selectAll,
  uid,
  useFormValidation,
  useUniDirective
} from '@windwalker-io/unicorn-next';

useFormValidation();

export class FormkitHandler {
  constructor(protected el: HTMLElement, protected uid: string) {
    this.registerValidation();
    this.autoCheckOther();
    this.toggleSelectOtherInput();
  }

  async registerValidation() {
    const form = this.el.querySelector('form') || this.el.closest('form');

    if (!form) {
      return;
    }

    const routeKey = 'formkit.action.' + this.uid;

    if (hasRoute(routeKey)) {
      const action = route(routeKey);
      const button = this.el.querySelector<HTMLButtonElement>('[data-task=submit]')!;

      button?.addEventListener('click', () => {
        form.action = action;
        form.requestSubmit();

        setTimeout(() => {
          form.removeAttribute('action');
        }, 500);
      });
    }

    form.addEventListener('submit', (e) => {
      let invalid = 0;
      let scrollTarget: HTMLElement | undefined = undefined;
      const $form = e.currentTarget as HTMLFormElement;

      // 驗證選擇列表
      // -----------------------------
      // const fields = $form.querySelectorAll<HTMLDivElement>('.input-list-container[required]');

      // 驗證矩陣
      // -----------------------------
      const grids = form.querySelectorAll<HTMLElement>('.c-grid-scale[required]');

      for (const grid of grids) {
        const $rows = grid.querySelectorAll('tbody > tr');

        // 移除前次驗證的資訊
        grid.closest<HTMLElement>('.form-group')!.classList.remove('has-invalid');

        for (const $row of $rows) {
          const $inputs = Array.from(
            $row.querySelectorAll<HTMLInputElement>('[type=checkbox], [type=radio]')
          );
          const checked = $inputs.filter((input) => input.checked);

          // 移除前次驗證的資訊
          // $row.closest('.form-group').removeClass('has-invalid');
          $row.querySelector('.invalid-feedback')?.remove();

          for (const $input of $inputs) {
            $input.setCustomValidity('');
          }

          // 確認沒有勾選就產生錯誤提示
          if (checked.length === 0) {
            const text = __('unicorn.message.validation.value.missing');
            const help = html(`<small class="invalid-feedback form-control-tooltip d-block">${text}</small>`);

            // 設定 HTML5 驗證結果
            for (const $input of $inputs) {
              $input.setCustomValidity(text);
            }

            // 插入提示
            $row.querySelector('.c-row-text')!.appendChild(help);
            grid.closest<HTMLElement>('.form-group')!.classList.add('has-invalid');

            // 準備滑動到第一個物件
            if (!scrollTarget) {
              scrollTarget = grid;
            }

            invalid++;
          }
        }
      }

      if (invalid > 0) {
        if (scrollTarget) {
          scrollTarget.scrollIntoView();
        }

        e.stopImmediatePropagation();
        e.stopPropagation();
        e.preventDefault();
      }
    });
  }

  autoCheckOther() {
    selectAll<HTMLInputElement>('.js-other-text', (el) => {
      el.addEventListener('input', () => {
        const option = el.closest('[data-input-option]')
          ?.querySelector<HTMLInputElement>('[data-radio-item-input], [data-checkbox-item-input]');

        if (option) {
          option.checked = true;
        }
      });
    });
  }

  toggleSelectOtherInput() {
    const selectInputs = selectAll<HTMLSelectElement>('select[data-field-input]');

    for (const selectInput of selectInputs) {
      selectInput.addEventListener('change', () => toggle(selectInput));

      toggle(selectInput);
    }

    function toggle(selectInput: HTMLSelectElement) {
      const option = selectInput.querySelector<HTMLOptionElement>('option[data-other-option]');
      const otherInput = selectInput.closest('.l-form-select-wrapper')
        ?.querySelector<HTMLInputElement>('.js-other-text');

      if (option && otherInput) {
        if (option.selected) {
          otherInput.style.display = 'block';
        } else {
          otherInput.style.display = 'none';
        }
      }
    }
  }
}

export const ready = useUniDirective<HTMLElement>(
  'formkit',
  {
    mounted(el, { value }) {
      const uniId = value || uid();

      module(el, 'formkit', (el) => new FormkitHandler(el, uniId))
    }
  }
);

export interface FormkitModule {
  FormkitHandler: typeof FormkitHandler;
  ready: typeof ready;
}
